RENAMES={'test_free_trial_uses_no_reference_or_offsets_and_keeps_both_terms': 'test_free_trial_uses_no_reference_or_offsets_and_only_free_term', 'test_lower_and_inverse_via_W_matches_conjunctionReverse': 'test_lower_and_inverse_via_W_matches_intersectionReverse', 'test_lower_total_explore_cannot_win_with_worse_reconstruction': 'test_only_strictly_lower_reconstruction_wins_and_tie_keeps_greedy', 'test_kwarg_forwarding_through_conjunctionReverse': 'test_kwarg_forwarding_through_intersectionReverse', 'test_kwarg_forwarding_through_disjunctionReverse': 'test_kwarg_forwarding_through_unionReverse', 'test_student_checkpoint_migrates_shared_weights_and_adam_by_name': 'test_student_checkpoint_migrates_shared_weights_and_momentum_by_name'}
REASONS['test_compiled_operator_diagonal.py']='New exact AOT conditional-backward regression for the production free inverse: active LDU diagonal gradient and inactive zero gradient have compatible dense layouts.'
def tests(source):
 tree=ast.parse(source) if source else ast.Module(body=[])
 out={}
 def visit(nodes,prefix=''):
  for node in nodes:
   if isinstance(node,ast.ClassDef):visit(node.body,prefix+node.name+'::')
   elif isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef)) and node.name.startswith('test_'):
    start=min([node.lineno]+[d.lineno for d in node.decorator_list]);out[prefix+node.name]={'start':start,'end':node.end_lineno,'body':'\n'.join(source.splitlines()[start-1:node.end_lineno])}
 visit(tree.body);return out
manifest=[]
with zipfile.ZipFile(HERE/'before.zip') as z:
 names=set(n for n in z.namelist() if n.startswith('test/') and n.endswith('.py'))
 names.update(str(p.relative_to(ROOT)) for p in (ROOT/'test').rglob('*.py'))
 for name in sorted(names):
  old=z.read(name).decode() if name in z.namelist() else ''
  path=ROOT/name;new=path.read_text() if path.exists() else ''
  if old==new:continue
  dest=HERE/'ports'/Path(name).name;dest.mkdir(parents=True,exist_ok=True)
  (dest/'old.py.txt').write_text(old);(dest/'new.py.txt').write_text(new)
  before,after=tests(old),tests(new)
  cases=[]
  for test,body in before.items():
   prefix,separator,leaf=test.rpartition('::')
   renamed=RENAMES.get(test,RENAMES.get(leaf or test))
   target=test if test in after else ((prefix+separator+renamed) if renamed is not None and prefix else renamed)
   if target not in after:target=None
   cases.append(dict(old=test,new=target,body_changed=target is None or body['body']!=after[target]['body'],old_lines=[body['start'],body['end']],new_lines=None if target is None else [after[target]['start'],after[target]['end']]))
  manifest.append(dict(file=name,old=str((dest/'old.py.txt').relative_to(HERE)),new=str((dest/'new.py.txt').relative_to(HERE)),reason=REASONS[Path(name).name],cases=cases,added=sorted(set(after)-{c['new'] for c in cases}),old_sha256=hashlib.sha256(old.encode()).hexdigest(),new_sha256=hashlib.sha256(new.encode()).hexdigest()))
(HERE/'ports.json').write_text(json.dumps(manifest,indent=2))
print(f'{len(manifest)} complete file pairs saved')
